assert len(rows) == 40 and len({r["id"] for r in rows}) == 40
for r in rows:   # Step 28: the basic kitchen devices run as their own types
    if r["id"] in ("M01", "M02", "M03", "M04", "M05", "M06", "M08"):
        r["runtime"] = r["id"]
doc = {"_doc": "Step 27, the canonical 40-machine catalog (generated by tools/catalog/build_catalog.py -- edit there). A machine whose `requires` lists a system the game does not have yet cannot be built and does nothing (no invented benefit); `runtime` names the model type of the ones that run today.",
       "systems_present": ["portions", "packs", "customers", "sizes", "lanes", "upkeep", "kernels", "oil", "heat_model"], "machines": rows}
json.dump(doc, open(OUT, "w"), indent=1, ensure_ascii=False)
print("wrote", OUT, len(rows))
